SELECT CASE WHEN departments.budget >= 4405000 THEN 'high' WHEN departments.budget >= 1607000 THEN 'mid' ELSE 'low' END AS budget_bucket, MAX(employees.hire_date) AS last_hire_date FROM employees INNER JOIN departments ON departments.id = employees.dept_id WHERE departments.dept_name IN ('Finance', 'HR', 'Sales') GROUP BY CASE WHEN departments.budget >= 4405000 THEN 'high' WHEN departments.budget >= 1607000 THEN 'mid' ELSE 'low' END ORDER BY last_hire_date DESC, budget_bucket DESC
